window.GOLF_BUNDLE={"tabs": [{"pagePath": "pages/home/index", "text": "打球", "iconPath": "assets/home.png", "selectedIconPath": "assets/home-active.png"}, {"pagePath": "pages/history/index", "text": "记录", "iconPath": "assets/history.png", "selectedIconPath": "assets/history-active.png"}, {"pagePath": "pages/stats/index", "text": "统计", "iconPath": "assets/stats.png", "selectedIconPath": "assets/stats-active.png"}, {"pagePath": "pages/profile/index", "text": "我的", "iconPath": "assets/profile.png", "selectedIconPath": "assets/profile-active.png"}], "globalCSS": "page{background:#f6f8f5;color:#203d31;font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",sans-serif;font-size:28rpx}view,text,button,input,textarea{box-sizing:border-box}button{font-size:28rpx;border-radius:22rpx;padding:0 28rpx;min-height:88rpx;line-height:88rpx;background:#edf3ee;color:#176b48;font-weight:600;margin:0}button::after{border:none}button[disabled]{opacity:.4}input{height:92rpx;padding:20rpx 26rpx;background:#fff;border:1rpx solid #e2eae3;border-radius:20rpx}textarea{width:100%;background:#fff;border-radius:20rpx;padding:20rpx;height:200rpx}.page{padding:32rpx 32rpx 64rpx}.eyebrow{font-size:21rpx;letter-spacing:5rpx;color:#73927e;font-weight:600}.title{font-size:48rpx;font-weight:650;line-height:1.4;margin:12rpx 0}.sub,.muted{color:#819087;font-size:25rpx;line-height:1.7}.section{font-size:32rpx;font-weight:600;margin:40rpx 0 22rpx}.card{background:#fff;border-radius:28rpx;padding:30rpx;margin-bottom:24rpx;border:1rpx solid #e9eee8}.row{display:flex;align-items:center;justify-content:space-between;gap:18rpx}.wrap{flex-wrap:wrap}.grow{flex:1;min-width:0}.primary{background:#176b48;color:#fff}.dark{background:#174c35;color:#fff}.dark .muted{color:#c3d8c9}.soft{color:#176b48;background:#edf4ec}.hero{height:400rpx;border-radius:32rpx;overflow:hidden;position:relative;margin:28rpx 0;background:#265c36}.hero image{height:100%;width:100%}.shade{position:absolute;inset:0;background:linear-gradient(0deg,rgba(9,45,27,.83),rgba(0,0,0,0) 90%);padding:38rpx;display:flex;flex-direction:column;justify-content:flex-end;color:#fff}.hero .title{font-size:44rpx}.hero .sub{color:#e7f1e6}.hero button{margin-top:22rpx;background:#fff;color:#176b48;width:100%}.metrics{display:flex;gap:14rpx;margin:24rpx 0}.metric{flex:1;text-align:center;background:white;border-radius:24rpx;padding:24rpx 8rpx}.num{font-size:45rpx;font-weight:600;display:block;margin:8rpx 0}.label{font-size:22rpx;color:#849087}.link{color:#176b48;font-size:26rpx}.avatar{width:76rpx;height:76rpx;flex-shrink:0;border-radius:50%;background:#ecf3e6;display:flex;align-items:center;justify-content:center;color:#176b48;font-size:30rpx;font-weight:600}.pill{display:inline-block;padding:10rpx 20rpx;border-radius:30rpx;background:#eef5ed;color:#50745b;font-size:22rpx}.choices{display:flex;gap:14rpx;flex-wrap:wrap;margin:20rpx 0}.choice{padding:18rpx 26rpx;border-radius:18rpx;background:#edf1ed;color:#75837a;min-width:108rpx;text-align:center}.choice.active{background:#176b48;color:#fff}.empty{text-align:center;padding:60rpx 24rpx;color:#859389;line-height:1.8}.empty .num{color:#b1c7ac;font-size:70rpx}.course-img{width:100%;height:260rpx;border-radius:20rpx;margin-bottom:20rpx}.divider{height:1rpx;background:#edf0eb;margin:24rpx 0}.footer-note{text-align:center;color:#96a197;font-size:21rpx;margin:35rpx 0}.space{margin-top:24rpx}.badge{font-size:22rpx;color:#9d7029;background:#fbf4df;border-radius:12rpx;padding:8rpx 14rpx}.danger{color:#b75041}.small{font-size:23rpx}.segment{display:flex;background:#e8eee7;padding:8rpx;border-radius:20rpx;margin:26rpx 0}.segment view{flex:1;text-align:center;padding:18rpx;border-radius:16rpx;color:#6c8172}.segment .active{background:#fff;color:#176b48;font-weight:600}.bottom{padding-bottom:env(safe-area-inset-bottom)}\n", "pages": {"pages/home/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{},onShow(){run(()=>{const d=S.read();const r=d.rounds.find(x=>x.status==='finished');this.setData({profile:d.profile,active:S.active()||null,stats:S.stats(),recent:r?Object.assign({},r,E.summary(r,'me'),{date:S.date(r.createdAt)}):null});});},start(){if(this.data.active)go('score','?id='+this.data.active.id);else go('courses');},courses(){go('courses');},friends(){go('friends');},profile(){tab('profile');},history(){tab('history');},result(){go('result','?id='+this.data.recent.id);}});\n", "wxml": "<view class=\"page\">\n<view class=\"row\"><view><view class=\"eyebrow\">GREEN DAYS, GOOD GAMES</view><view class=\"title\">去球场，找回好状态</view></view><view class=\"avatar\" bindtap=\"profile\">青</view></view><view class=\"sub\">你好，{{profile.name}}。把每一次进步记下来。</view>\n<view class=\"hero\"><image src=\"/assets/course.jpg\" mode=\"aspectFill\"/><view class=\"shade\"><view class=\"eyebrow\" style=\"color:#e0ecd9\">LET’S PLAY GOLF</view><view class=\"title\">下一杆，值得期待。</view><view class=\"sub\">{{active ? active.courseName : '从第一洞开始，专注当下的每一杆'}}</view><button bindtap=\"start\">{{active ? '继续记分 · 第 ' + active.currentHole + ' 洞 →' : '开启一场好球 →'}}</button></view></view>\n<view class=\"metrics\"><view class=\"metric\"><text class=\"num\">{{stats.rounds}}</text><text class=\"label\">已完成球局</text></view><view class=\"metric\"><text class=\"num\">{{stats.best}}</text><text class=\"label\">18 洞最佳</text></view><view class=\"metric\"><text class=\"num\">{{stats.holes}}</text><text class=\"label\">累计球洞</text></view></view>\n<view class=\"row section\"><text>球场时光</text><text class=\"link\" bindtap=\"courses\">选择球场 →</text></view><view class=\"card row\" bindtap=\"friends\"><view class=\"avatar\">＋</view><view class=\"grow\"><view>和球友一起挥杆</view><view class=\"muted\">管理常用球友，轻松同组记分</view></view><text>›</text></view>\n<view class=\"row section\"><text>最近一轮</text><text class=\"link\" bindtap=\"history\">全部记录 →</text></view><view wx:if=\"recent\" class=\"card\" bindtap=\"result\"><view class=\"row\"><view><view>{{recent.courseName}}</view><view class=\"muted\">{{recent.date}} · {{recent.holes.length}} 洞</view></view><view><text class=\"num\">{{recent.totalText}}</text><text class=\"pill\">{{recent.diffText}}</text></view></view></view><view wx:else class=\"card empty\">还没有球局记录<view/>从今天开始，记录你的高球时光</view><view class=\"footer-note\">青野 · 每一杆，都是新的开始</view>\n</view>\n", "css": "/* Shared visual system: app.wxss */\n", "title": "青野 · GOLF"}, "pages/courses/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{query:'',items:[]},onLoad(){this.setData({items:S.courses});},search(e){const q=e.detail.value.trim();this.setData({query:e.detail.value,items:S.courses.filter(c=>(c.name+c.city).includes(q))});},select(e){go('create','?course='+e.currentTarget.dataset.id);}});\n", "wxml": "<view class=\"page\">\n<view class=\"eyebrow\">FIND YOUR NEXT FAIRWAY</view><view class=\"title\">好球场，好时光。</view><view class=\"sub\">选择本轮球场，开始你的记分之旅</view><input class=\"space\" placeholder=\"搜索球场名称 / 城市\" value=\"{{query}}\" bindinput=\"search\"/><view class=\"row section\"><text>精选球场</text><text class=\"pill\">{{items.length}} 家</text></view><view class=\"muted\">内置球场为本地演示资料，标准杆与码数需按实际球场调整。</view><view class=\"card space\" wx:for=\"{{items}}\" wx:key=\"id\"><image class=\"course-img\" src=\"{{item.image}}\" mode=\"aspectFill\"/><view class=\"row\"><view class=\"grow\"><view style=\"font-size:32rpx;font-weight:600\">{{item.name}}</view><view class=\"muted\">{{item.city}} · 18 洞 · Par 72</view><view class=\"sub\">{{item.tag}}</view></view><button size=\"mini\" class=\"primary\" data-id=\"{{item.id}}\" bindtap=\"select\">选择</button></view></view><view wx:if=\"!items.length\" class=\"empty\">没有找到匹配的球场，试试城市或名称关键词。</view>\n</view>\n", "css": "/* Shared visual system: app.wxss */\n", "title": "发现球场"}, "pages/create/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{modes:[{id:'all',label:'18 洞'},{id:'front',label:'前 9 洞'},{id:'back',label:'后 9 洞'}],mode:'all',tees:['白 Tee','蓝 Tee','红 Tee'],tee:'白 Tee',selected:[],count:1},onLoad(o){this.courseId=o.course;},onShow(){run(()=>{const d=S.read(),c=S.courses.find(x=>x.id===this.courseId);if(!c)throw Error('球场不存在');this.setData({course:c,profile:d.profile,selected:this.data.selected.filter(id=>d.friends.some(f=>f.id===id)),friends:d.friends});this.refresh();});},refresh(){this.setData({friends:this.data.friends.map(f=>Object.assign({},f,{selected:this.data.selected.includes(f.id)})),count:this.data.selected.length+1});},mode(e){this.setData({mode:e.currentTarget.dataset.id});},tee(e){this.setData({tee:e.currentTarget.dataset.value});},manage(){go('friends');},toggle(e){const id=e.currentTarget.dataset.id;let a=this.data.selected.slice();if(a.includes(id))a=a.filter(x=>x!==id);else if(a.length<3)a.push(id);else return wx.showToast({title:'每组最多 4 人',icon:'none'});this.setData({selected:a});this.refresh();},start(){run(()=>{const r=S.create({courseId:this.courseId,mode:this.data.mode,tee:this.data.tee,friendIds:this.data.selected});wx.redirectTo({url:'/pages/score/index?id='+r.id});});}});\n", "wxml": "<view class=\"page\">\n<view class=\"eyebrow\">A NEW ROUND</view><view class=\"title\">准备好，出发。</view><view class=\"card space\"><image class=\"course-img\" src=\"/assets/course.jpg\" mode=\"aspectFill\"/><view style=\"font-size:34rpx;font-weight:600\">{{course.name}}</view><view class=\"muted\">{{course.city}} · 演示球场资料</view></view><view class=\"section\">打几洞？</view><view class=\"choices\"><view wx:for=\"{{modes}}\" wx:key=\"id\" class=\"choice {{mode===item.id?'active':''}}\" data-id=\"{{item.id}}\" bindtap=\"mode\">{{item.label}}</view></view><view class=\"section\">选择发球台</view><view class=\"choices\"><view wx:for=\"{{tees}}\" wx:key=\"*this\" class=\"choice {{tee===item?'active':''}}\" data-value=\"{{item}}\" bindtap=\"tee\">{{item}}</view></view><view class=\"muted\">发球台仅作为本轮标签，码数为示例数据。</view><view class=\"row section\"><text>同组球友 · {{count}} / 4</text><text class=\"link\" bindtap=\"manage\">管理球友 →</text></view><view class=\"card row\"><view class=\"avatar\">我</view><view class=\"grow\">{{profile.name}}</view><text class=\"pill\">本轮记分员</text></view><view wx:for=\"{{friends}}\" wx:key=\"id\" class=\"card row\" data-id=\"{{item.id}}\" bindtap=\"toggle\"><view class=\"avatar\">{{item.name[0]}}</view><view class=\"grow\">{{item.name}}</view><text class=\"pill\">{{item.selected?'已加入 ✓':'＋ 加入'}}</text></view><view class=\"muted\">可单人开局，最多 4 人。每洞记录自动保存到本机。</view><button class=\"primary space\" bindtap=\"start\">开始本轮记分 →</button>\n</view>\n", "css": "/* Shared visual system: app.wxss */\n", "title": "创建对局"}, "pages/score/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{round:null,canUndo:false,saved:'已保存'},onLoad(o){this.rid=o.id;},onShow(){this.refresh();},refresh(){run(()=>{const r=S.getRound(this.rid);if(!r)throw Error('球局不存在');if(r.status!=='active'){wx.redirectTo({url:'/pages/result/index?id='+r.id});return;}const current=r.currentHole,h=r.holes.find(h=>h.number===current);this.setData({round:r,current,hole:h,index:r.holes.findIndex(h=>h.number===current),nine:current<=9?'front':'back',visibleHoles:r.holes.filter(x=>current<=9?x.number<=9:x.number>9).map(x=>Object.assign({},x,{done:r.players.every(p=>!!r.scores[p.id][x.number])})),players:r.players.map(p=>Object.assign({},p,{summary:E.summary(r,p.id),recorded:!!r.scores[p.id][current],score:r.scores[p.id][current]||{strokes:h.par,putts:2,penalties:0,fairway:null,green:null}}))});});},commit(fn){run(()=>{const before=S.getRound(this.rid);fn(before);this.previous=before;this.setData({canUndo:true,saved:'已保存'});this.refresh();});},record(e){const p=this.data.players.find(p=>p.id===e.currentTarget.dataset.pid);this.commit(()=>S.saveScore(this.rid,p.id,this.data.current,p.score));},step(e){const {pid,field,step}=e.currentTarget.dataset;const p=this.data.players.find(p=>p.id===pid);const s=Object.assign({},p.score);s[field]+=Number(step);this.commit(()=>S.saveScore(this.rid,pid,this.data.current,s));},hit(e){const {pid,field}=e.currentTarget.dataset,p=this.data.players.find(p=>p.id===pid),s=Object.assign({},p.score);s[field]=s[field]===null?true:s[field]===true?false:null;this.commit(()=>S.saveScore(this.rid,pid,this.data.current,s));},clear(e){const pid=e.currentTarget.dataset.pid;confirm('清空本洞','仅清空该球友在本洞的记录，可撤销。',()=>this.commit(r=>{const n=E.clone(r);delete n.scores[pid][this.data.current];S.replace(n);}));},undo(){if(!this.previous)return;run(()=>{S.replace(this.previous);this.previous=null;this.setData({canUndo:false});this.refresh();});},par(e){const v=this.data.hole.par+Number(e.currentTarget.dataset.step);if(v<3||v>5)return;this.commit(r=>{const n=E.clone(r);n.holes.find(h=>h.number===this.data.current).par=v;if(v===3)n.players.forEach(p=>{const s=n.scores[p.id][this.data.current];if(s)s.fairway=null;});S.replace(n);});},jump(number){run(()=>{const r=S.getRound(this.rid);r.currentHole=number;S.replace(r);this.refresh();});},selectHole(e){this.jump(Number(e.currentTarget.dataset.number));},move(e){const next=this.data.round.holes[this.data.index+Number(e.currentTarget.dataset.step)];if(next)this.jump(next.number);},switchNine(e){const front=e.currentTarget.dataset.nine==='front',h=this.data.round.holes.find(x=>front?x.number<=9:x.number>9);if(h)this.jump(h.number);else wx.showToast({title:'本轮未选择这九洞',icon:'none'});},result(){go('result','?id='+this.rid);},finish(){const r=S.getRound(this.rid),missing=r.players.reduce((a,p)=>a+r.holes.length-E.summary(r,p.id).played,0);confirm('结束本轮',missing?'还有 '+missing+' 条球友球洞记录未填写。保存为不完整球局？空洞不会按零杆统计。':'保存成绩并结束本轮？结束后成绩将只读。',()=>{S.finish(this.rid);wx.redirectTo({url:'/pages/result/index?id='+this.rid});});}});\n", "wxml": "<view class=\"page\">\n<block wx:if=\"round\"><view class=\"row\"><view class=\"grow\"><view class=\"eyebrow\">ROUND IN PROGRESS</view><view style=\"font-size:32rpx;font-weight:600;margin-top:12rpx\">{{round.courseName}}</view><view class=\"muted\">{{round.tee}} · {{round.holes.length}} 洞</view></view><text class=\"pill\">{{saved}}</text></view><view class=\"segment\"><view class=\"{{nine==='front'?'active':''}}\" data-nine=\"front\" bindtap=\"switchNine\">前九洞</view><view class=\"{{nine==='back'?'active':''}}\" data-nine=\"back\" bindtap=\"switchNine\">后九洞</view></view><view class=\"holes\"><view wx:for=\"{{visibleHoles}}\" wx:key=\"number\" data-number=\"{{item.number}}\" bindtap=\"selectHole\" class=\"hole {{current===item.number?'selected':''}} {{item.done?'done':''}}\">{{item.number}}<text>{{item.done?'•':'·'}}</text></view></view><view class=\"card dark space\"><view class=\"row\"><view><view class=\"muted\">当前球洞</view><view style=\"font-size:66rpx;font-weight:600\">{{current}} <text style=\"font-size:25rpx\">HOLE</text></view></view><view style=\"text-align:right\"><view style=\"font-size:38rpx\">Par {{hole.par}}</view><view class=\"muted\">{{hole.yards}} 码 · 示例</view></view></view><view class=\"row space\"><text>本洞标准杆</text><view class=\"row\"><button size=\"mini\" data-step=\"-1\" bindtap=\"par\">−</button><text>{{hole.par}}</text><button size=\"mini\" data-step=\"1\" bindtap=\"par\">＋</button></view></view></view><view class=\"muted small\">总杆包含推杆和罚杆。未记分球洞保持空白；初次点按即记录显示值。</view>\n<view class=\"card space\" wx:for=\"{{players}}\" wx:key=\"id\" wx:for-item=\"p\"><view class=\"row\"><view class=\"avatar\">{{p.name[0]}}</view><view class=\"grow\"><view style=\"font-weight:600\">{{p.name}}</view><view class=\"muted\">已记 {{p.summary.played}} 洞 · 总杆 {{p.summary.totalText}} · {{p.summary.diffText}}</view></view><text class=\"pill\">{{p.recorded?'已记录':'待记分'}}</text></view><view class=\"divider\"/><view class=\"row\"><text>本洞总杆</text><view class=\"stepper\"><button data-pid=\"{{p.id}}\" data-field=\"strokes\" data-step=\"-1\" bindtap=\"step\">−</button><text class=\"score-value\">{{p.score.strokes}}</text><button data-pid=\"{{p.id}}\" data-field=\"strokes\" data-step=\"1\" bindtap=\"step\">＋</button></view></view><view wx:if=\"!p.recorded\" class=\"space\"><button data-pid=\"{{p.id}}\" bindtap=\"record\">按当前值记分 · {{p.score.strokes}} 杆</button></view><view class=\"divider\"/><view class=\"row\"><text class=\"muted\">推杆</text><view class=\"stepper small-step\"><button data-pid=\"{{p.id}}\" data-field=\"putts\" data-step=\"-1\" bindtap=\"step\">−</button><text>{{p.score.putts}}</text><button data-pid=\"{{p.id}}\" data-field=\"putts\" data-step=\"1\" bindtap=\"step\">＋</button></view><text class=\"muted\">罚杆</text><view class=\"stepper small-step\"><button data-pid=\"{{p.id}}\" data-field=\"penalties\" data-step=\"-1\" bindtap=\"step\">−</button><text>{{p.score.penalties}}</text><button data-pid=\"{{p.id}}\" data-field=\"penalties\" data-step=\"1\" bindtap=\"step\">＋</button></view></view><view class=\"row space\"><text class=\"muted\">球道命中 {{hole.par===3?'（Par 3 不适用）':''}}</text><button size=\"mini\" disabled=\"{{hole.par===3}}\" data-pid=\"{{p.id}}\" data-field=\"fairway\" bindtap=\"hit\">{{p.score.fairway===null?'未记录':p.score.fairway?'命中 ✓':'未命中 ×'}}</button></view><view class=\"row space\"><text class=\"muted\">果岭命中 GIR</text><button size=\"mini\" data-pid=\"{{p.id}}\" data-field=\"green\" bindtap=\"hit\">{{p.score.green===null?'未记录':p.score.green?'命中 ✓':'未命中 ×'}}</button></view><view wx:if=\"p.recorded\" class=\"space link small\" data-pid=\"{{p.id}}\" bindtap=\"clear\">清空该球友本洞记录</view></view>\n<view class=\"row space\"><button class=\"grow\" disabled=\"{{index===0}}\" data-step=\"-1\" bindtap=\"move\">← 上一洞</button><button class=\"primary grow\" disabled=\"{{index===round.holes.length-1}}\" data-step=\"1\" bindtap=\"move\">下一洞 →</button></view><view class=\"row space\"><button class=\"grow\" disabled=\"{{!canUndo}}\" bindtap=\"undo\">撤销上次修改</button><button class=\"grow\" bindtap=\"result\">成绩与排名</button></view><button class=\"primary space\" bindtap=\"finish\">结束本轮</button><view class=\"footer-note\">离开页面可随时继续 · 每次修改立即保存</view></block><view wx:else class=\"empty\">没有找到进行中的球局</view>\n</view>\n", "css": ".holes{display:flex;gap:8rpx}.hole{flex:1;background:#fff;text-align:center;border-radius:15rpx;padding:17rpx 0;color:#7f8f80;font-size:26rpx}.hole text{display:block;font-size:17rpx;line-height:15rpx}.hole.done{color:#176b48}.hole.selected{background:#176b48;color:white}.stepper{display:flex;align-items:center;gap:24rpx}.stepper button{width:76rpx;min-height:76rpx;line-height:76rpx;padding:0;font-size:36rpx}.score-value{font-size:56rpx;min-width:68rpx;text-align:center;font-weight:600}.small-step{gap:10rpx}.small-step button{width:50rpx;min-height:58rpx;line-height:58rpx;font-size:28rpx}\n", "title": "逐洞记分"}, "pages/result/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{round:null},onLoad(o){this.rid=o.id;},onShow(){run(()=>{const r=S.getRound(this.rid);if(!r)return;this.setData({round:r,date:S.date(r.createdAt),mine:E.summary(r,'me'),ranking:E.ranking(r),partial:r.players.some(p=>E.summary(r,p.id).played!==r.holes.length),rows:r.holes.map(h=>({number:h.number,par:h.par,values:r.players.map(p=>{const s=r.scores[p.id][h.number];return s?s.strokes:'—';})}))});});},resume(){const stack=typeof getCurrentPages==='function'?getCurrentPages():[];const prev=stack[stack.length-2];if(prev&&prev.route==='pages/score/index'&&prev.rid===this.rid){wx.navigateBack();}else wx.redirectTo({url:'/pages/score/index?id='+this.rid});},edit(e){if(this.data.round.status!=='active')return;run(()=>{const r=S.getRound(this.rid);r.currentHole=Number(e.currentTarget.dataset.number);S.replace(r);this.resume();});},home(){tab('home');},copy(){const r=this.data.round;wx.setClipboardData({data:`青野 · ${r.courseName}\\n${this.data.date}\\n`+this.data.ranking.map(p=>`${p.rank}. ${p.name} ${p.totalText}杆 (${p.diffText}) 已记${p.played}/${r.holes.length}洞`).join('\\n')});}});\n", "wxml": "<view class=\"page\">\n<block wx:if=\"round\"><view class=\"eyebrow\">{{round.status==='active'?'LIVE SCORECARD':'ROUND COMPLETE'}}</view><view class=\"title\">{{round.status==='active'?'每一杆，都算数。':'好球，值得回味。'}}</view><view class=\"sub\">{{round.courseName}} · {{date}} · {{round.tee}}</view><view class=\"card dark space\"><view class=\"muted\">我的本轮总杆</view><view class=\"row\"><text style=\"font-size:100rpx;font-weight:600\">{{mine.totalText}}</text><text style=\"font-size:46rpx\">{{mine.diffText}}</text></view><view class=\"row\"><text>已记 {{mine.played}} / {{round.holes.length}} 洞</text><text>前九 {{mine.front}} · 后九 {{mine.back}}</text></view></view><view wx:if=\"partial\" class=\"badge\">不完整成绩 · 各球友完成洞数可能不同，总杆排名仅供参考</view><view class=\"section\">同组排名</view><view class=\"card\"><view class=\"row rank\" wx:for=\"{{ranking}}\" wx:key=\"id\"><text class=\"rank-no\">{{item.rank}}</text><view class=\"grow\"><view>{{item.name}}</view><view class=\"muted\">{{item.played}} 洞 · {{item.diffText}}</view></view><text style=\"font-size:40rpx;font-weight:600\">{{item.totalText}}</text></view></view><view class=\"section\">逐洞记分卡</view><view class=\"sub\">横向滑动查看所有球友。{{round.status==='active'?'点球洞行可回洞修改。':'未填写的球洞显示 —。'}}</view><scroll-view scroll-x class=\"scoretable space\"><view class=\"table\" style=\"min-width:{{180+round.players.length*170}}rpx\"><view class=\"table-row table-head\"><text>洞 / Par</text><text wx:for=\"{{round.players}}\" wx:key=\"id\">{{item.name}}</text></view><view class=\"table-row\" wx:for=\"{{rows}}\" wx:key=\"number\" data-number=\"{{item.number}}\" bindtap=\"edit\"><text>{{item.number}} / {{item.par}}</text><text wx:for=\"{{item.values}}\" wx:for-item=\"value\" wx:key=\"index\">{{value}}</text></view></view></scroll-view><view class=\"section\">我的技术统计</view><view class=\"metrics\"><view class=\"metric\"><text class=\"num\">{{mine.putts}}</text><text class=\"label\">总推杆</text></view><view class=\"metric\"><text class=\"num\">{{mine.penalties}}</text><text class=\"label\">总罚杆</text></view><view class=\"metric\"><text class=\"num\">{{mine.girRate}}</text><text class=\"label\">果岭命中</text></view></view><view class=\"card row\"><text>球道命中率</text><text>{{mine.fwRate}}</text></view><button wx:if=\"round.status==='active'\" class=\"primary\" bindtap=\"resume\">继续记分 →</button><button wx:else class=\"primary\" bindtap=\"home\">返回首页</button><button class=\"space\" bindtap=\"copy\">复制本轮成绩</button></block><view wx:else class=\"empty\">找不到这轮成绩，请从记录页重新进入。</view>\n</view>\n", "css": ".rank{padding:18rpx 0;border-bottom:1rpx solid #edf0e9}.rank:last-child{border:0}.rank-no{width:50rpx;color:#7d9d69;font-size:36rpx}.scoretable{background:#fff;border-radius:24rpx}.table-row{display:flex;padding:24rpx 0;border-bottom:1rpx solid #edf0e9}.table-row text{width:170rpx;flex-shrink:0;text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:0 8rpx}.table-row text:first-child{width:180rpx}.table-head{background:#eaf2e8;color:#176b48;font-weight:600}\n", "title": "本轮成绩"}, "pages/history/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{filters:[{id:'all',label:'全部'},{id:'active',label:'进行中'},{id:'finished',label:'已完成'}],filter:'all',query:'',items:[]},onShow(){this.refresh();},refresh(){run(()=>this.setData({items:S.read().rounds.filter(r=>(this.data.filter==='all'||r.status===this.data.filter)&&r.courseName.includes(this.data.query.trim())).map(r=>Object.assign({},r,E.summary(r,'me'),{date:S.date(r.createdAt)}))}));},filter(e){this.setData({filter:e.currentTarget.dataset.id});this.refresh();},search(e){this.setData({query:e.detail.value});this.refresh();},open(e){const d=e.currentTarget.dataset;go(d.status==='active'?'score':'result','?id='+d.id);},remove(e){const id=e.currentTarget.dataset.id;confirm('删除球局','删除后无法恢复，建议先在“我的”导出备份。',()=>{S.mutate(d=>d.rounds=d.rounds.filter(r=>r.id!==id));this.refresh();});},home(){tab('home');}});\n", "wxml": "<view class=\"page\">\n<view class=\"eyebrow\">YOUR GOLF JOURNAL</view><view class=\"title\">留住每一场好球</view><view class=\"sub\">每次出发，都有新的收获</view><view class=\"segment\"><view wx:for=\"{{filters}}\" wx:key=\"id\" class=\"{{filter===item.id?'active':''}}\" data-id=\"{{item.id}}\" bindtap=\"filter\">{{item.label}}</view></view><input placeholder=\"搜索球场名称\" bindinput=\"search\" value=\"{{query}}\"/><view wx:for=\"{{items}}\" wx:key=\"id\" class=\"card space\"><view class=\"row\" data-id=\"{{item.id}}\" data-status=\"{{item.status}}\" bindtap=\"open\"><view class=\"grow\"><text class=\"pill\">{{item.status==='active'?'进行中':'已结束'}}</text><view style=\"font-size:31rpx;font-weight:600;margin:18rpx 0 8rpx\">{{item.courseName}}</view><view class=\"muted\">{{item.date}} · {{item.players.length}} 人 · {{item.played}}/{{item.holes.length}} 洞</view></view><view style=\"text-align:right\"><text class=\"num\">{{item.totalText}}</text><text class=\"pill\">{{item.diffText}}</text></view></view><view class=\"divider\"/><view class=\"row\"><text class=\"muted\">{{item.tee}}</text><text class=\"link\" data-id=\"{{item.id}}\" data-status=\"{{item.status}}\" bindtap=\"open\">{{item.status==='active'?'继续记分':'查看记分卡'}} →</text><text class=\"danger small\" data-id=\"{{item.id}}\" bindtap=\"remove\">删除</text></view></view><view wx:if=\"!items.length\" class=\"empty\"><view class=\"num\">⚑</view><view>这里还没有球局</view><view class=\"sub\">你的下一场好球，从现在开始</view><button class=\"primary space\" bindtap=\"home\">去打球</button></view>\n</view>\n", "css": "/* Shared visual system: app.wxss */\n", "title": "打球记录"}, "pages/stats/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{s:{trend:[]}},onShow(){run(()=>this.setData({s:S.stats()}));}});\n", "wxml": "<view class=\"page\">\n<view class=\"eyebrow\">YOUR GAME, IN FOCUS</view><view class=\"title\">看见自己的进步</view><view class=\"sub\">用数据认识每一次挥杆</view><view class=\"card dark space\"><view class=\"muted\">18 洞平均杆</view><view style=\"font-size:98rpx;font-weight:600;margin:14rpx 0\">{{s.avg}}</view><view class=\"row\"><text>最佳 {{s.best}} 杆</text><text>已完成 {{s.rounds}} 轮</text></view></view><view class=\"metrics\"><view class=\"metric\"><text class=\"num\">{{s.holes}}</text><text class=\"label\">累计球洞</text></view><view class=\"metric\"><text class=\"num\">{{s.putts}}</text><text class=\"label\">平均推杆 / 洞</text></view><view class=\"metric\"><text class=\"num\">{{s.penalties}}</text><text class=\"label\">累计罚杆</text></view></view><view class=\"section\">技术表现</view><view class=\"card\"><view class=\"row\"><text>球道命中率 FIR</text><text style=\"font-size:38rpx;color:#176b48\">{{s.fwRate}}</text></view><view class=\"divider\"/><view class=\"row\"><text>果岭命中率 GIR</text><text style=\"font-size:38rpx;color:#176b48\">{{s.girRate}}</text></view><view class=\"sub space\">命中率仅统计明确记录的洞；Par 3 不计球道命中率。</view></view><view class=\"section\">最近 8 轮</view><view class=\"card\"><view wx:if=\"s.trend.length\" class=\"chart\"><view class=\"bar-group\" wx:for=\"{{s.trend}}\" wx:key=\"index\"><text class=\"small\">{{item.score}}</text><view class=\"bar-track\"><view class=\"bar\" style=\"height:{{item.height}}%\"/></view><view class=\"tiny\">{{item.played}}洞</view><view class=\"tiny\">{{item.shortDate}}</view></view></view><view wx:else class=\"empty\">完成第一轮后，在这里看见你的成绩趋势。</view></view><view class=\"muted\">仅统计已结束球局中“我”的成绩。平均杆与最佳杆仅采用已记满的 18 洞球局；趋势展示本轮总杆与洞数，9 洞和未完整成绩不能直接比较。</view>\n</view>\n", "css": ".chart{display:flex;align-items:flex-end;height:330rpx;gap:12rpx}.bar-group{flex:1;min-width:0;text-align:center}.bar-track{height:210rpx;display:flex;align-items:flex-end;justify-content:center;margin:12rpx 0}.bar{width:32rpx;border-radius:10rpx 10rpx 0 0;background:linear-gradient(#a9c29b,#216d47)}.tiny{font-size:17rpx;color:#809086;white-space:nowrap}\n", "title": "数据统计"}, "pages/friends/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{name:'',friends:[]},onShow(){this.refresh();},refresh(){run(()=>this.setData({friends:S.read().friends}));},input(e){this.setData({name:e.detail.value});},add(){run(()=>{const name=this.data.name.trim();if(!name)throw Error('请输入昵称');S.mutate(d=>{if(d.friends.some(f=>f.name===name))throw Error('已有同名球友');d.friends.push({id:S.id(),name});});this.setData({name:''});this.refresh();});},rename(e){const id=e.currentTarget.dataset.id,f=this.data.friends.find(f=>f.id===id);wx.showModal({title:'修改昵称',editable:true,content:f.name,success:r=>{if(r.confirm)run(()=>{const name=(r.content||'').trim();if(!name||name.length>16)throw Error('昵称为 1–16 个字');S.mutate(d=>{if(d.friends.some(x=>x.id!==id&&x.name===name))throw Error('已有同名球友');d.friends.find(x=>x.id===id).name=name;});this.refresh();});}});},remove(e){const id=e.currentTarget.dataset.id;confirm('移除球友','已有球局记录仍会保留。',()=>{S.mutate(d=>d.friends=d.friends.filter(f=>f.id!==id));this.refresh();});}});\n", "wxml": "<view class=\"page\">\n<view class=\"eyebrow\">BETTER TOGETHER</view><view class=\"title\">好球，和好友一起</view><view class=\"sub\">本地球友名册，同组记分无需注册</view><view class=\"card space\"><view class=\"row\"><input class=\"grow\" maxlength=\"16\" placeholder=\"输入球友昵称\" value=\"{{name}}\" bindinput=\"input\"/><button class=\"primary\" bindtap=\"add\">添加</button></view></view><view class=\"section\">我的球友 · {{friends.length}}</view><view class=\"card row\" wx:for=\"{{friends}}\" wx:key=\"id\"><view class=\"avatar\">{{item.name[0]}}</view><view class=\"grow\"><view>{{item.name}}</view><view class=\"muted\">下次一起出发</view></view><text class=\"link\" data-id=\"{{item.id}}\" bindtap=\"rename\">编辑</text><text class=\"danger small\" data-id=\"{{item.id}}\" bindtap=\"remove\">移除</text></view><view wx:if=\"!friends.length\" class=\"empty\">添加一位球友，让下一轮更精彩。</view><view class=\"footer-note\">修改名册不会改变已有球局中的球友姓名</view>\n</view>\n", "css": "/* Shared visual system: app.wxss */\n", "title": "球友管理"}, "pages/profile/index": {"js": "const {S,run,go,tab,confirm}=require('../../services/ui');\nconst E=require('../../services/engine');\nPage({data:{profile:{name:''},stats:{},importing:false,exportPath:''},onShow(){this.refresh();},refresh(){run(()=>{const d=S.read();this.setData({profile:d.profile,stats:S.stats(),friends:d.friends.length});});},edit(){wx.showModal({title:'你的昵称',editable:true,content:this.data.profile.name,success:r=>{if(r.confirm)run(()=>{const name=(r.content||'').trim();if(!name||name.length>16)throw Error('昵称为 1–16 个字');S.mutate(d=>d.profile.name=name);this.refresh();});}});},friends(){go('friends');},history(){tab('history');},stats(){tab('stats');},about(){wx.showModal({title:'青野 · 高尔夫记分',content:'选择球场 → 创建球局 → 逐洞记分。点击 +/- 或“按当前值记分”才会创建本洞记录；命中状态依次切换未记录/命中/未命中。总杆已含推杆与罚杆。每次修改自动保存；结束前可回洞修改。内置球场为演示数据，支持逐洞调整 Par 3–5。本版离线使用，不含定位、实时联机和官方差点。',showCancel:false});},exportData(){run(()=>{const data=JSON.stringify(S.read(),null,2),path=wx.env.USER_DATA_PATH+'/green-golf-backup.json';wx.getFileSystemManager().writeFileSync(path,data,'utf8');this.backup=data;this.setData({exportPath:path});wx.showToast({title:'备份已生成',icon:'success'});});},shareBackup(){if(!wx.shareFileMessage)return wx.showToast({title:'请使用复制备份内容',icon:'none'});wx.shareFileMessage({filePath:this.data.exportPath,fileName:'青野高球备份.json',fail(){wx.showToast({title:'未分享，可复制备份内容',icon:'none'});}});},copyBackup(){wx.setClipboardData({data:this.backup});},showImport(){this.setData({importing:!this.data.importing});},backupInput(e){this.raw=e.detail.value;},restore(){confirm('覆盖并恢复','当前本地数据将被备份内容替换，请确认已导出现有数据。',()=>{S.importData(this.raw||'');this.setData({importing:false,exportPath:''});this.refresh();wx.showToast({title:'恢复成功'});});}});\n", "wxml": "<view class=\"page\">\n<view class=\"eyebrow\">MY GREEN DAYS</view><view class=\"title\">享受挥杆，也享受生活</view><view class=\"card row space\"><view class=\"avatar\" style=\"width:112rpx;height:112rpx;font-size:44rpx\">{{profile.name[0]}}</view><view class=\"grow\"><view style=\"font-size:36rpx;font-weight:600\">{{profile.name}}</view><view class=\"muted\">{{profile.goal}}</view></view><text class=\"link\" bindtap=\"edit\">编辑</text></view><view class=\"metrics\"><view class=\"metric\"><text class=\"num\">{{stats.rounds}}</text><text class=\"label\">打球轮数</text></view><view class=\"metric\"><text class=\"num\">{{friends}}</text><text class=\"label\">常用球友</text></view><view class=\"metric\"><text class=\"num\">{{stats.best}}</text><text class=\"label\">最佳 18 洞</text></view></view><view class=\"card\"><view class=\"menu row\" bindtap=\"friends\"><text>球友管理</text><text>›</text></view><view class=\"menu row\" bindtap=\"history\"><text>我的打球记录</text><text>›</text></view><view class=\"menu row\" bindtap=\"stats\"><text>数据统计</text><text>›</text></view><view class=\"menu row\" bindtap=\"exportData\"><text>导出本地数据备份</text><text>↓</text></view><view class=\"menu row\" bindtap=\"showImport\"><text>从备份恢复</text><text>↑</text></view><view class=\"menu row\" bindtap=\"about\"><text>关于青野 / 使用说明</text><text>›</text></view></view><view wx:if=\"importing\" class=\"card\"><view class=\"sub\">粘贴备份 JSON。恢复将覆盖本机数据，请先导出备份。</view><textarea class=\"space\" maxlength=\"-1\" bindinput=\"backupInput\" placeholder=\"粘贴备份内容\"/><view class=\"row space\"><button class=\"grow\" bindtap=\"showImport\">取消</button><button class=\"primary grow\" bindtap=\"restore\">恢复备份</button></view></view><view wx:if=\"exportPath\" class=\"card\"><view class=\"sub\">备份已写入本机文件，可复制内容保存在手机备忘录；也可通过微信分享文件。</view><button class=\"space\" bindtap=\"shareBackup\">分享备份文件</button><button class=\"space\" bindtap=\"copyBackup\">复制备份内容</button></view><view class=\"footer-note\">青野 GOLF · v1.0.0<view/>数据仅存于当前设备，请定期备份</view>\n</view>\n", "css": ".menu{min-height:105rpx;border-bottom:1rpx solid #edf0e9}.menu:last-child{border:0}\n", "title": "我的"}}, "modules": {"services/ui": "const S=require('./store');\nfunction run(fn){try{return fn();}catch(e){wx.showToast({title:e.message||'操作失败',icon:'none',duration:3000});return null;}}\nfunction go(page,query=''){wx.navigateTo({url:'/pages/'+page+'/index'+query});}\nfunction tab(page){wx.switchTab({url:'/pages/'+page+'/index'});}\nfunction confirm(title,content,fn){wx.showModal({title,content,success:r=>{if(r.confirm)run(fn);}});}\nmodule.exports={S,run,go,tab,confirm};\n", "services/store": "// Repository boundary: replace storage operations here to connect cloud/API later.\nconst E=require('./engine');const KEY='greenGolf.v1';\nconst pars=[4,5,3,4,4,5,3,4,4,4,3,5,4,4,3,5,4,4];\nconst courses=[{id:'pine',name:'松林湖高尔夫俱乐部',city:'杭州',tag:'湖畔 · 林克斯风格'},{id:'green',name:'青山高尔夫球会',city:'上海',tag:'山地 · 开阔球道'},{id:'bay',name:'云湾高尔夫俱乐部',city:'苏州',tag:'滨水 · 轻松挥杆'}].map(c=>Object.assign(c,{image:'/assets/course.jpg',holes:pars.map((par,i)=>({number:i+1,par,yards:[368,492,156,402,385,510,172,390,410,375,163,505,389,406,178,522,397,420][i]}))}));\nfunction initial(){return {version:1,profile:{id:'me',name:'高球爱好者',goal:'享受每一次挥杆'},friends:[{id:'f1',name:'林一'},{id:'f2',name:'小夏'}],rounds:[],selectedCourse:'pine'};}\nfunction init(){if(!wx.getStorageSync(KEY))wx.setStorageSync(KEY,initial());}\nfunction read(){init();const d=wx.getStorageSync(KEY);if(d.version!==1)throw Error('数据版本不兼容，请先导出备份');return E.clone(d);}\nfunction write(d){try{wx.setStorageSync(KEY,d);}catch(e){throw Error('保存失败：本地空间不足，请导出备份后清理空间');}return d;}\nfunction mutate(fn){const d=read();const v=fn(d);write(d);return v;}\nfunction id(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7);}\nfunction getRound(rid){return read().rounds.find(r=>r.id===rid);}\nfunction active(){return read().rounds.find(r=>r.status==='active');}\nfunction create(opts){return mutate(d=>{if(d.rounds.some(r=>r.status==='active'))throw Error('请先继续或结束进行中的球局');const c=courses.find(c=>c.id===opts.courseId);if(!c)throw Error('请选择球场');const ids=Array.from(new Set(['me'].concat(opts.friendIds||[])));if(ids.length>4)throw Error('每组最多 4 人');const people=[d.profile].concat(d.friends);const players=ids.map(pid=>{const p=people.find(x=>x.id===pid);if(!p)throw Error('球友不存在');return {id:p.id,name:p.name};});let holes=E.clone(c.holes);if(opts.mode==='front')holes=holes.slice(0,9);if(opts.mode==='back')holes=holes.slice(9);const r={id:id(),courseId:c.id,courseName:c.name,tee:opts.tee||'白 Tee',holes,players,scores:{},status:'active',createdAt:Date.now(),updatedAt:Date.now(),currentHole:holes[0].number};players.forEach(p=>r.scores[p.id]={});d.rounds.unshift(r);return r;});}\nfunction replace(r){return mutate(d=>{let i=d.rounds.findIndex(x=>x.id===r.id);if(i<0)throw Error('球局不存在');r.updatedAt=Date.now();d.rounds[i]=r;return r;});}\nfunction saveScore(rid,pid,num,s){return replace(E.setScore(getRound(rid),pid,num,s));}\nfunction finish(rid){const r=getRound(rid);if(!r||r.status!=='active')throw Error('球局不可结束');if(!r.players.every(p=>E.summary(r,p.id).played>0))throw Error('每位球友至少记一洞后才能结束');r.status='finished';r.finishedAt=Date.now();return replace(r);}\nfunction stats(){const rs=read().rounds.filter(r=>r.status==='finished');const entries=rs.map(r=>({r,s:E.summary(r,'me')})).filter(x=>x.s.played);const full=entries.filter(x=>x.s.played===18&&x.r.holes.length===18);const sum=k=>entries.reduce((a,x)=>a+x.s[k],0);const fwN=sum('fwN'),girN=sum('girN');return {rounds:entries.length,holes:sum('played'),best:full.length?Math.min(...full.map(x=>x.s.total)):'—',avg:full.length?(full.reduce((a,x)=>a+x.s.total,0)/full.length).toFixed(1):'—',putts:sum('played')?(sum('putts')/sum('played')).toFixed(1):'—',penalties:sum('penalties'),fwRate:fwN?Math.round(sum('fw')/fwN*100)+'%':'—',girRate:girN?Math.round(sum('gir')/girN*100)+'%':'—',trend:entries.slice(0,8).reverse().map(x=>({date:date(x.r.createdAt),shortDate:date(x.r.createdAt).slice(5),score:x.s.total,played:x.s.played,height:Math.max(10,Math.min(100,x.s.total/x.s.played/8*100))}))};}\nfunction date(t){const d=new Date(t);return `${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')}`;}\nfunction importData(raw){const d=JSON.parse(raw);if(d.version!==1||!d.profile||d.profile.id!=='me'||typeof d.profile.name!=='string'||!Array.isArray(d.friends)||!Array.isArray(d.rounds))throw Error('备份格式无效');let activeN=0;const roundIds=new Set();d.rounds.forEach(r=>{if(!r.id||roundIds.has(r.id)||!['active','finished'].includes(r.status)||!Array.isArray(r.holes)||![9,18].includes(r.holes.length)||!Array.isArray(r.players)||r.players.length<1||r.players.length>4||!r.players.some(p=>p.id==='me')||!r.scores)throw Error('球局格式无效');roundIds.add(r.id);if(r.status==='active')activeN++;const ns=new Set();r.holes.forEach(h=>{if(!Number.isInteger(h.number)||h.number<1||h.number>18||ns.has(h.number)||![3,4,5].includes(h.par))throw Error('球洞格式无效');ns.add(h.number);});const ps=new Set();r.players.forEach(p=>{if(!p.id||ps.has(p.id)||typeof p.name!=='string'||!r.scores[p.id])throw Error('球友格式无效');ps.add(p.id);Object.keys(r.scores[p.id]).forEach(n=>{if(!ns.has(Number(n)))throw Error('球洞编号无效');E.validate(r.scores[p.id][n]);});});if(!ns.has(r.currentHole))throw Error('当前球洞无效');});if(activeN>1)throw Error('备份含多个进行中球局');if(d.friends.some(f=>!f.id||f.id==='me'||typeof f.name!=='string')||new Set(d.friends.map(f=>f.id)).size!==d.friends.length)throw Error('球友格式无效');write(d);}\nmodule.exports={KEY,init,read,mutate,courses,getRound,active,create,replace,saveScore,finish,stats,date,importData,id};\n", "services/engine": "const clone = x => JSON.parse(JSON.stringify(x));\nfunction validate(s) {\n if (!s || !Number.isInteger(s.strokes) || s.strokes < 1 || s.strokes > 30) throw Error('总杆须为 1–30 的整数');\n if (!Number.isInteger(s.putts) || s.putts < 0 || s.putts > s.strokes) throw Error('推杆不能超过总杆');\n if (!Number.isInteger(s.penalties) || s.penalties < 0 || s.penalties + s.putts > s.strokes) throw Error('推杆与罚杆之和不能超过总杆');\n if (![null,true,false].includes(s.fairway) || ![null,true,false].includes(s.green)) throw Error('命中状态无效');\n return s;\n}\nfunction summary(round, playerId) {\n let total=0, par=0, putts=0, penalties=0, played=0, fw=0, fwN=0, gir=0, girN=0, front=0, back=0;\n round.holes.forEach(h=>{const s=(round.scores[playerId]||{})[h.number];if(!s)return;played++;total+=s.strokes;par+=h.par;putts+=s.putts;penalties+=s.penalties;if(h.number<=9)front+=s.strokes;else back+=s.strokes;if(h.par!==3 && s.fairway!==null){fwN++;if(s.fairway)fw++;}if(s.green!==null){girN++;if(s.green)gir++;}});\n const diff=total-par;\n return {total,par,putts,penalties,played,diff,diffText:played?(diff>0?'+'+diff:diff===0?'E':String(diff)):'—',totalText:played?total:'—',front,back,fw,fwN,gir,girN,fwRate:fwN?Math.round(fw/fwN*100)+'%':'—',girRate:girN?Math.round(gir/girN*100)+'%':'—'};\n}\nfunction ranking(r){const rows=r.players.map(p=>Object.assign({},p,summary(r,p.id)));rows.sort((a,b)=>(b.played>0)-(a.played>0)||a.total-b.total);let rank=0;return rows.map((p,i)=>{if(!i||p.total!==rows[i-1].total||p.played!==rows[i-1].played)rank=i+1;return Object.assign(p,{rank:p.played?rank:'—'});});}\nfunction setScore(r,pid,num,s){if(r.status!=='active')throw Error('已结束球局不可修改');if(!r.players.some(p=>p.id===pid)||!r.holes.some(h=>h.number===num))throw Error('球友或球洞不存在');validate(s);let n=clone(r);n.scores[pid][num]=clone(s);return n;}\nmodule.exports={validate,summary,ranking,setScore,clone};\n"}};